#!/bin/bash

# Example script for saving architecture documentation to a file
# This script demonstrates how to save generated architecture documentation
# to a markdown file. Actual content should be generated by Claude based on
# project analysis.

set -e

# Default output filename
OUTPUT_FILE="${1:-ARCHITECTURE.md}"

# Function to generate example architecture content
generate_example_content() {
    local project_name="$1"
    local description="$2"

    cat << EOF
# Project Architecture: ${project_name}

## Overview
- **Description**: ${description}
- **Technology Stack**: [Analyze from package.json and config files]
- **Project Type**: [Identify from project structure]

## Directory Structure

\`\`\`
[Generated directory tree using 'find' or 'tree' command]
\`\`\`

### Key Directories
- [Directory 1]: [Purpose]
- [Directory 2]: [Purpose]

## Architecture Components

### Entry Points
- [Main entry file]: [Role]

### Core Modules
- [Module 1]: [Description]
- [Module 2]: [Description]

## Development Workflow

### Available Scripts
\`\`\`bash
# From package.json
[Command 1]: [Description]
[Command 2]: [Description]
\`\`\`

## Dependencies

### Runtime Dependencies
- [Dependency 1]: [Version, purpose]
- [Dependency 2]: [Version, purpose]

### Development Dependencies
- [Dev dependency 1]: [Version, purpose]
- [Dev dependency 2]: [Version, purpose]

---
*Generated by project-architecture-diagram skill on $(date)*
EOF
}

# Main execution
if [ "$#" -gt 2 ]; then
    echo "Usage: $0 [output_filename] [project_name] [description]"
    echo "Example: $0 ARCHITECTURE.md \"My Project\" \"A sample project description\""
    exit 1
fi

PROJECT_NAME="${2:-$(basename "$(pwd)")}"
DESCRIPTION="${3:-$(grep -o '"description": *"[^"]*"' package.json 2>/dev/null | head -1 | cut -d'"' -f4 || echo "Project description")}"

echo "Generating architecture documentation for: $PROJECT_NAME"
echo "Saving to: $OUTPUT_FILE"

# Generate and save content
generate_example_content "$PROJECT_NAME" "$DESCRIPTION" > "$OUTPUT_FILE"

echo "Architecture documentation saved to $OUTPUT_FILE"
echo "Note: This is a template. Please review and update with actual project analysis."